#!/bin/bash
# rollback-gate.sh <openrc|systemd> <image-dir>: the boot rollback (patronus-guard, docs/embedded-routers.md 12.14) under a
# REAL U-Boot (Alpine u-boot-qemu, qemu_arm64) on QEMU aarch64 virt, with the shipped root of this image.
# What is the same as on the GL-AX1800: the whole bootloader state machine (bootcmd prefix, pat_boot/pat_trial/pat_revert/
# pat_failed, the counters, setexpr/itest, the order "count + save, then boot"; "read both old parts, then write") is
# generated by the image's own `patronus-guard env-install` inside the booted guest, from settings; the Linux side
# (trial detection, health checks, confirm, failure report, revert report) is the image's own code under its own init.
# What differs (board facts are settings, boot-guard.board): the volumes are virtio disks instead of UBI volumes
# (copy = `virtio read/write` instead of `ubi read/write`), the stock boot command is `run qboot` (virtio read + booti)
# instead of bootipq, the environment lives on a virtio disk (saved with `env export -c` + `virtio write`, loaded by a
# 3-line bootstrap in the pflash environment) instead of NAND, and there is no hardware watchdog (QEMU virt has none).
# The UBI side of the installer (save-prev/arm/ubi-write) is proven on nandsim (nandsim-proof.sh); here the harness plays
# upgrade-install's stage2 with the image's own `patronus-guard arm` against the environment disk.
# Disks (virtio, PCI order = U-Boot `virtio dev N` = Linux vdX): 0 rootfs (vda) 1 data (vdb) 2 env (vdc) 3 kernel
#   4 kernel_prev 5 rootfs_prev.
# Scenarios: good image confirms; bad images revert by themselves and the old image comes back healthy:
#   panic (init exits: kernel panic, panic=1), nonet (no address), webdead (web UI never starts, with a power cut in
#   the middle of its trial: the counters survive), hostapddead (hostapd binary broken), badkernel (kernel not bootable).
# Env: VIRT_KERNEL, UNIT_DIR (ci_ed25519), RESULTS, BOOT_TIMEOUT, SCENARIOS (default all), GUARD_WINDOW (default 120).
# Prints PASS/FAIL per check and "FAILED: none" when all passed.
set -uo pipefail
HERE=$(cd "$(dirname "$0")" && pwd)
INIT=${1:?usage: rollback-gate.sh <openrc|systemd> <image-dir>}; I=$(readlink -f "${2:?image dir}")
K=${VIRT_KERNEL:?VIRT_KERNEL}; KEY=${UNIT_DIR:?UNIT_DIR}/ci_ed25519
RES=${RESULTS:-/out/rollback-$INIT}; mkdir -p "$RES"; : > "$RES/results.txt"
TMO=${BOOT_TIMEOUT:-900}; WIN=${GUARD_WINDOW:-120}; ATT=${GUARD_ATTEMPTS:-2}
SCEN=${SCENARIOS:-panic nonet webdead hostapddead badkernel}
UB=${UBOOT_BIN:-/usr/share/u-boot/qemu_arm64/u-boot.bin}
SQ=$(ls "$I"/root.squashfs)
W=$(mktemp -d "${TMPDIR:-/tmp}/ax-rb.XXXX"); QP=; trap 'kill $QP 2>/dev/null; rm -rf "$W"' EXIT
SSHP=${GATE_SSHP:-2322}; WEBP=${GATE_WEBP:-8543}
fails=()
pass() { echo "PASS: $*" | tee -a "$RES/results.txt"; }
fail() { echo "FAIL: $*" | tee -a "$RES/results.txt"; fails+=("$1"); }
note() { echo "  .. $*" | tee -a "$RES/results.txt"; }
SSHO=(-i "$KEY" -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o LogLevel=ERROR -o ConnectTimeout=8)
R() { ssh "${SSHO[@]}" -p $SSHP root@127.0.0.1 "$@"; }
ENVF=$W/env.img
FWC=$W/fw_env.config; echo "$ENVF 0x0 0x40000" > "$FWC"
E() { fw_printenv -c "$FWC" -n "$1" 2>/dev/null; }

# --- the test roots: the shipped root with the virt kernel's kmods (as qemu-gate.sh) and the QEMU board facts ---
unsquashfs -q -d "$W/r" "$SQ" >/dev/null || { echo "unsquashfs failed"; exit 1; }
KV=$(ls "$W/r/lib/modules"); rm -rf "$W/r/lib/modules/$KV" "$W/r/etc/modules.d"; mkdir -p "$W/r/etc/modules.d"
sh "$HERE/fetch-kmods.sh" virt "$W/r" "${KMOD_CACHE:-/cache/kmods}" || exit 1
depmod -b "$W/r" "$KV"; : > "$W/r/etc/patronus/qemu-kmods"
cat > "$W/r/etc/patronus/boot-guard.board" <<EOF
# QEMU virt + qemu_arm64 U-Boot (rollback-gate.sh): virtio disks play the UBI volumes
GUARD_ENV_MTD=/dev/vdc
GUARD_ENV_OFFSET=0x0
GUARD_ENV_SIZE=0x40000
GUARD_UB_BOOT="run qboot"
GUARD_UB_VOL=true
GUARD_UB_ENV_ADDR=0x4f000000
GUARD_UB_ROOT_ADDR=0x50000000
GUARD_UB_ROOT_MAX=0x8000000
GUARD_UB_KERNEL_ADDR=0x58000000
GUARD_UB_KERNEL_MAX=0x2000000
GUARD_UB_RD_ROOT='virtio dev 5 && setexpr pat_n \${pat_rsz} / 0x200 && virtio read \${pat_ra} 0 \${pat_n}'
GUARD_UB_RD_KERNEL='virtio dev 4 && setexpr pat_n \${pat_ksz} + 0x1ff && setexpr pat_n \${pat_n} / 0x200 && virtio read \${pat_ka} 0 \${pat_n}'
GUARD_UB_WR_ROOT='virtio dev 0 && setexpr pat_n \${pat_rsz} / 0x200 && virtio write \${pat_ra} 0 \${pat_n}'
GUARD_UB_WR_KERNEL='virtio dev 3 && setexpr pat_n \${pat_ksz} + 0x1ff && setexpr pat_n \${pat_n} / 0x200 && virtio write \${pat_ka} 0 \${pat_n}'
GUARD_UB_SAVE='virtio dev 2 && env export -c -s 0x40000 \${pat_ea} && virtio write \${pat_ea} 0 0x200'
GUARD_UB_WDT=
GUARD_UB_KARGS=
GUARD_ATTEMPTS=$ATT
GUARD_WINDOW=$WIN
EOF
mkroot() { # name build-suffix [modification]: a squashfs test root
  n=$1; b=$2; rm -rf "$W/m"; cp -a "$W/r" "$W/m"
  sed -i "s/^BUILD=.*/BUILD=rbgate-$b-$INIT/" "$W/m/etc/patronus-release"
  case "${3:-}" in
    panic)  printf '#!/bin/sh\necho "rbgate: init exits on purpose"\nexit 1\n' > "$W/m/usr/sbin/patronus-init" ;;
    nonet)  printf '#!/bin/sh\nexit 0\n' > "$W/m/usr/share/udhcpc/default.script" ;;
    webdead) rm -f "$W/m/usr/bin/patronus-web"; printf '#!/bin/sh\necho "rbgate: web UI broken on purpose" >&2\nexit 1\n' > "$W/m/usr/bin/patronus-web"; chmod 755 "$W/m/usr/bin/patronus-web" ;;
    hostapddead) printf '#!/bin/sh\necho "rbgate: hostapd broken on purpose" >&2\nexit 1\n' > "$W/m/usr/sbin/hostapd" ;;
  esac
  mksquashfs "$W/m" "$W/$n.sq" -comp xz -b 256K -noappend -no-xattrs -all-root -quiet >/dev/null; rm -rf "$W/m"
  bs=$(stat -c %s "$W/$n.sq"); pad=$(( (bs + 4095) / 4096 * 4096 )); truncate -s $pad "$W/$n.sq"
}
mkroot good1 good1; mkroot good2 good2
for s in $SCEN; do case $s in badkernel) cp "$W/good2.sq" "$W/$s.sq";; *) mkroot "$s" "$s" "$s";; esac; done
rm -rf "$W/r"
# a kernel nobody can boot: same size, no ARM64 Image magic
head -c "$(stat -c %s "$K")" /dev/zero > "$W/badkernel.k"

# --- disks ---
truncate -s 128M "$W/rootfs.img" "$W/rootfs_prev.img"; truncate -s 32M "$W/kernel.img" "$W/kernel_prev.img"
truncate -s 256M "$W/data.img"; mkfs.ext4 -q -F -L patronus_data "$W/data.img"
KB=$(stat -c %s "$K"); KBLK=$(( (KB + 511) / 512 ))
# the "stock" environment: what bootipq is on the board (boot the kernel volume), then the stock failsafe
cat > "$W/env.txt" <<EOF
bootcmd=run qboot; echo stock-failsafe; sleep 100000
kernel_addr_r=0x40400000
qboot=virtio dev 3 && virtio read \${kernel_addr_r} 0 $(printf '0x%x' $KBLK) && booti \${kernel_addr_r} - \${fdtcontroladdr}
bootargs=root=/dev/vda rootfstype=squashfs ro console=ttyAMA0 patronus.data=/dev/vdb panic=1
EOF
mkenvimage -s 0x40000 -o "$ENVF" "$W/env.txt"; truncate -s 1M "$ENVF"
# pflash: the 3-line bootstrap (the board's U-Boot loads its environment from NAND by itself)
printf 'bootdelay=0\nbootcmd=virtio scan; virtio dev 2 && virtio read 0x4f000000 0 0x200 && env import -c 0x4f000000 0x40000 && run bootcmd\n' > "$W/pf.txt"
mkenvimage -s 0x40000 -o "$W/pflash1.img" "$W/pf.txt"; truncate -s 64M "$W/pflash1.img"
put() { dd if="$1" of="$2" bs=1M conv=notrunc status=none; }   # write an image at the start of a "volume"
put "$W/good1.sq" "$W/rootfs.img"; put "$K" "$W/kernel.img"; CUR=good1; CURK=$K

N=0
boot() { # start QEMU (U-Boot -> the env script -> Linux); resets (guest restart, panic) stay in the same QEMU
  N=$((N + 1)); SER="$RES/serial-$INIT-$N.txt"
  qemu-system-aarch64 -M virt -accel tcg -cpu cortex-a53 -smp 2 -m 1024 -bios "$UB" \
    -drive if=pflash,unit=1,file="$W/pflash1.img",format=raw \
    -drive file="$W/rootfs.img",if=none,id=d0,format=raw -device virtio-blk-pci,drive=d0 \
    -drive file="$W/data.img",if=none,id=d1,format=raw -device virtio-blk-pci,drive=d1 \
    -drive file="$ENVF",if=none,id=d2,format=raw -device virtio-blk-pci,drive=d2 \
    -drive file="$W/kernel.img",if=none,id=d3,format=raw -device virtio-blk-pci,drive=d3 \
    -drive file="$W/kernel_prev.img",if=none,id=d4,format=raw -device virtio-blk-pci,drive=d4 \
    -drive file="$W/rootfs_prev.img",if=none,id=d5,format=raw -device virtio-blk-pci,drive=d5 \
    -netdev user,id=n0,hostfwd=tcp:127.0.0.1:$SSHP-:22,hostfwd=tcp:127.0.0.1:$WEBP-:443 -device virtio-net-pci,netdev=n0 \
    -display none -monitor none -serial file:"$SER" &
  QP=$!
}
stop() { [ -n "$QP" ] && { R sync >/dev/null 2>&1; kill $QP 2>/dev/null; wait $QP 2>/dev/null; }; QP=; }
wait_ssh() { t0=$(date +%s); until R true 2>/dev/null; do
  kill -0 $QP 2>/dev/null || return 1; [ $(( $(date +%s) - t0 )) -gt "$TMO" ] && return 1; sleep 5; done; }
# guest state through ssh
gstate() { R '/usr/sbin/patronus-guard status --json' 2>/dev/null; }
wait_guard() { # pattern: until the guest's guard status JSON matches
  t0=$(date +%s); while :; do s=$(gstate); case "$s" in *$1*) echo "$s"; return 0;; esac
    [ $(( $(date +%s) - t0 )) -gt "$TMO" ] && { echo "$s"; return 1; }; sleep 5; done; }
web_ok() { c=$(curl -sk -o /dev/null -w '%{http_code}' -m 20 https://127.0.0.1:$WEBP/); case "$c" in 200|30?) ;; *) echo "web HTTP $c"; return 1;; esac; }
sha() { head -c "$(stat -c %s "$2")" "$1" | sha256sum | cut -d' ' -f1; }

# harness = upgrade-install stage2: keep the running image as the rollback, arm the trial with the image's own
# `patronus-guard arm` (same environment writer and values as on the board), then write the new image
upgrade() { # new-root-name [new-kernel-file]
  nr=$1; nk=${2:-$K}
  put "$CURK" "$W/kernel_prev.img"; put "$W/$CUR.sq" "$W/rootfs_prev.img"
  mkdir -p "$W/run" "$W/gconf"; cp "$HERE/overlay/etc/patronus/boot-guard.conf" "$W/gconf/"
  printf 'GUARD_ENV_MTD=%s\nGUARD_ENV_SIZE=0x40000\nGUARD_ATTEMPTS=%s\nGUARD_WINDOW=%s\n' "$ENVF" "$ATT" "$WIN" > "$W/gconf/boot-guard.board"
  printf 'PREV_KSZ=%s\nPREV_RSZ=%s\n' "$(stat -c %s "$CURK")" "$(stat -c %s "$W/$CUR.sq")" > "$W/run/prev-sizes"
  echo "BUILD=rbgate-$CUR-$INIT" > "$W/run/release"
  GUARD_CONF_DIR=$W/gconf GUARD_RUN=$W/run PATRONUS_DATA=$W/hostdata GUARD_RELEASE=$W/run/release \
    sh "$HERE/overlay/usr/sbin/patronus-guard" arm "rbgate-$nr-$INIT" >/dev/null 2>&1 || { echo "arm failed"; return 1; }
  dd if=/dev/zero of="$W/rootfs.img" bs=1M count=128 conv=notrunc status=none; put "$W/$nr.sq" "$W/rootfs.img"
  dd if=/dev/zero of="$W/kernel.img" bs=1M count=32 conv=notrunc status=none; put "$nk" "$W/kernel.img"
  [ "$(E pat_state)" = trial ] && [ "$(E pat_left)" = "$ATT" ]
}

echo "== rollback gate $INIT: window ${WIN}s, $ATT boots, scenarios: $SCEN"
# 1. first boot of a rollback-capable image on the stock environment: the guest installs the bootloader script
boot
if wait_ssh && s=$(wait_guard '"installed":true'); then pass "env-install: the image installed its bootloader script"
  case "$(E bootcmd)" in "run pat_boot; run qboot; run pat_failed; echo stock-failsafe; sleep 100000") pass "bootcmd = stock with the guard around it";;
    *) fail "bootcmd: $(E bootcmd)";; esac
  [ "$(E pat_orig_bootcmd)" = "run qboot; echo stock-failsafe; sleep 100000" ] && pass "stock bootcmd kept" || fail "pat_orig_bootcmd"
else fail "first boot / env-install"; tail -20 "$SER"; fi
stop

# 2. a good image: trial, checks pass, confirmed
if upgrade good2; then pass "armed trial of good2 (pat_state=trial, $ATT boots)"; else fail "arm good2"; fi
boot
if wait_ssh && s=$(wait_guard '"state":"ok"'); then
  pass "good image confirmed itself"; note "$(echo "$s" | grep -o '"events":.*' | cut -c1-400)"
  R 'grep -o "patronus.trial=[0-9]*" /proc/cmdline' | grep -q 'patronus.trial=1' && pass "kernel got patronus.trial=1 from the bootloader" || fail "patronus.trial on the command line"
  [ "$(E pat_boots)" = 1 ] && [ "$(E pat_left)" = "" ] && pass "counters: 1 trial boot, none left after confirm" || fail "counters after confirm: boots=$(E pat_boots) left=$(E pat_left)"
  R 'grep -q "^BUILD=rbgate-good2-" /etc/patronus-release' && pass "running good2" || fail "not running good2"
  web_ok && pass "good2 web UI up" || fail "good2 web"
else fail "good image did not confirm"; note "$s"; fi
stop; CUR=good2; CURK=$K

# 3. bad images: each must revert to good2 by itself
for sc in $SCEN; do
  echo "== bad image: $sc"
  t0=$(date +%s)
  if [ $sc = badkernel ]; then upgrade badkernel "$W/badkernel.k" || fail "$sc: arm"; else upgrade "$sc" || fail "$sc: arm"; fi
  boot
  if [ $sc = webdead ]; then
    # power cut in the middle of the trial: wait until the bootloader counted the first boot, then pull the plug
    t1=$(date +%s); until [ "$(E pat_boots)" = 1 ]; do sleep 2; [ $(( $(date +%s) - t1 )) -gt 300 ] && break; done
    sleep 20; kill -9 $QP 2>/dev/null; wait $QP 2>/dev/null; QP=
    [ "$(E pat_boots)" = 1 ] && [ "$(E pat_state)" = trial ] && [ "$(E pat_left)" = "$((ATT - 1))" ] \
      && pass "$sc: power cut during the trial: counters kept (boots=1, left=$((ATT - 1)))" || fail "$sc: counters after power cut: $(E pat_boots)/$(E pat_left)/$(E pat_state)"
    boot
  fi
  ok=1
  # match THIS scenario's revert: an earlier scenario's "reverted" event is still in the log (and a bad image with ssh answers)
  if wait_ssh && s=$(wait_guard "\"event\":\"reverted\",\"detail\":\"trial of rbgate-$sc-$INIT failed"); then :; else ok=0; fi
  st=$(E pat_state); bo=$(E pat_boots)
  if [ $ok = 1 ] && R 'grep -q "^BUILD=rbgate-good2-" /etc/patronus-release'; then
    pass "$sc: reverted by itself to good2 in $(( $(date +%s) - t0 ))s (bootloader state $st, $bo trial boots)"
    [ "$bo" = "$ATT" ] && pass "$sc: the bad image got exactly $ATT boots" || fail "$sc: trial boots $bo (want $ATT)"
    [ "$(sha "$W/rootfs.img" "$W/good2.sq")" = "$(sha256sum < "$W/good2.sq" | cut -d' ' -f1)" ] && pass "$sc: rootfs volume = good2 byte for byte" || fail "$sc: rootfs content"
    [ "$(sha "$W/kernel.img" "$K")" = "$(sha256sum < "$K" | cut -d' ' -f1)" ] && pass "$sc: kernel volume = the old kernel" || fail "$sc: kernel content"
    # the revert is reported from the early boot; the web UI starts later (TCG, two gates in parallel): give it time
    t1=$(date +%s); until web_ok >/dev/null; do [ $(( $(date +%s) - t1 )) -gt "${WEB_WAIT:-180}" ] && break; sleep 5; done
    web_ok && pass "$sc: old image healthy again (web UI)" || fail "$sc: web after revert"
    d=$(echo "$s" | grep -o '"event":"reverted","detail":"[^"]*"' | tail -1); note "$d"
    case "$sc:$d" in panic:*kernel\ panic*|badkernel:*kernel\ panic*|nonet:*network\ FAIL*|webdead:*web\ FAIL*|hostapddead:*hostapd\ FAIL*) pass "$sc: revert reason recorded";;
      *) fail "$sc: revert reason: $d";; esac
    [ "$st" = idle ] && pass "$sc: bootloader state back to idle" || fail "$sc: state $st"
    sv=$(R 'if [ -d /run/systemd/system ]; then systemctl --failed --no-legend --plain; else rc-status -c 2>/dev/null; fi'); [ -z "$sv" ] && pass "$sc: no failed services after revert" || fail "$sc: failed services: $sv"
  else fail "$sc: did not come back on good2 (state $st, boots $bo)"; note "$s"; tail -25 "$SER" | sed 's/^/    /'
    # put good2 back by hand so the next scenario starts from a known state (no cascade)
    stop; put "$W/good2.sq" "$W/rootfs.img"; put "$K" "$W/kernel.img"; fw_setenv -c "$FWC" pat_state idle; fi
  stop
  cp "$ENVF" "$RES/env-after-$sc.img" 2>/dev/null
done

# 4. a revert that cannot work in the bootloader (its copy command fails): marked revert-failed and saved, no reset loop,
#    the stock boot command's fallback runs (here "stock-failsafe", on the GL unit its recovery web page)
if [ "${REVERTFAIL:-1}" = 1 ]; then
  echo "== revert that fails in the bootloader"
  if upgrade badkernel "$W/badkernel.k" && fw_setenv -c "$FWC" pat_rd_r false; then
    boot; t0=$(date +%s)
    until [ "$(E pat_state)" = revert-failed ]; do sleep 5; [ $(( $(date +%s) - t0 )) -gt "$TMO" ] && break; done
    sleep 45
    if [ "$(E pat_state)" = revert-failed ]; then pass "revertfail: state revert-failed saved after $(E pat_boots) trial boots"
      r=$(grep -ac "U-Boot 20" "$SER"); sleep 30
      [ "$(grep -ac "U-Boot 20" "$SER")" = "$r" ] && [ "$r" -le $((ATT + 2)) ] && pass "revertfail: no reset loop ($r bootloader starts in total)" || fail "revertfail: resets keep coming ($r)"
      grep -aq stock-failsafe "$SER" && pass "revertfail: the stock boot command's fallback runs" || fail "revertfail: no stock fallback"
    else fail "revertfail: state $(E pat_state)"; tail -25 "$SER" | sed 's/^/    /'; fi
  else fail "revertfail: arm"; fi
  stop
fi

fw_printenv -c "$FWC" > "$RES/env-final.txt" 2>&1
echo
if [ ${#fails[@]} -eq 0 ]; then echo "FAILED: none" | tee -a "$RES/results.txt"; exit 0; fi
echo "FAILED: ${fails[*]}" | tee -a "$RES/results.txt"; exit 1
